animation.code:
.hero__shot { opacity: 0; animation: shot-emerge 980ms var(--e-emerge) forwards; }
.hero__shot--1 { --tx: 110.9%; --ty: 76.9%; --r0: -4deg; animation-delay: 620ms; }
@keyframes shot-emerge {
  0%   { opacity: 1; transform: translate(var(--tx), var(--ty)) scale(.82) rotate(var(--r0)); }
  100% { opacity: 1; transform: none; }
}

shot.addEventListener('animationend', (ev) => {
  if (ev.animationName !== 'shot-emerge') return
  shot.animate(
    [{ transform: 'translateY(0) rotate(0)' }, { transform: `translateY(${d.y}px) rotate(${d.r}deg)` }, { transform: 'translateY(0) rotate(0)' }],
    { duration: d.dur, iterations: Infinity, easing: 'ease-in-out', delay: i * 240 })
})
/* o hover usa a propriedade `scale` separada, para compor com o transform animado */

.reveal { opacity: 0; transform: translateY(26px);
  transition: opacity var(--t-slow) var(--e-out), transform var(--t-slow) var(--e-out);
  transition-delay: var(--d, 0ms); }
.reveal.is-in { opacity: 1; transform: none; }

const io = new IntersectionObserver((entries) => entries.forEach((e) => {
  if (!e.isIntersecting) return
  e.target.classList.add('is-in'); io.unobserve(e.target)
}), { rootMargin: '0px 0px -12% 0px', threshold: 0.08 })
document.querySelectorAll('.reveal').forEach((el) => io.observe(el))

/* CSS: o 'pin' é só sticky */
.duo__runway { height: 320svh; }
.duo__stage  { position: sticky; top: 0; height: 100svh; }

// JS: rolagem → 0..1, suavizado, e só renderiza com o bloco na tela
const readProgress = () => {
  const span = runway.offsetHeight - stage.offsetHeight
  return Math.min(1, Math.max(0, -runway.getBoundingClientRect().top / span))
}
const ease = (t) => (t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
function frame() {
  current += (readProgress() - current) * 0.12      // lerp
  const t = ease(current)
  fold((Math.PI / 2) * (1 - t))                      // dobra a malha
  holder.rotation.y = Math.PI - (Math.PI / 2) * t    // vira da capa para a tela interna
  lean.x += (input.x - lean.x) * 0.08                // mouse/giroscópio, ±0.2 rad
  renderer.render(scene, camera)
  if (running) requestAnimationFrame(frame)
}

.site-header { position: sticky; top: 0; background: transparent;
  transition: background-color var(--t-med) var(--e-soft), box-shadow var(--t-med) var(--e-soft); }
.site-header.is-stuck { background: var(--c-page);
  box-shadow: 0 1px 0 rgba(36,35,29,.08), 0 12px 24px -20px rgba(36,35,29,.5); }

addEventListener('scroll', () => header.classList.toggle('is-stuck', scrollY > 12), { passive: true })

.nav__link::after { content: ''; position: absolute; left: 0; bottom: -2px; height: 2px; width: 100%;
  background: var(--c-accent-red); transform: scaleX(0); transform-origin: left center;
  transition: transform var(--t-med) var(--e-out); }
.nav__link:hover::after, .nav__link.is-active::after { transform: scaleX(1); }

.btn::after { content: ''; position: absolute; inset: 0; z-index: -1; border-radius: inherit;
  background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.22) 45%, transparent 70%);
  background-size: 220% 100%; background-position: 130% 0;
  transition: background-position 620ms var(--e-out); }
.btn:hover { transform: translateY(-2px); box-shadow: var(--sh-btn); }
.btn:hover::after { background-position: -30% 0; }
.btn:active { transform: translateY(0) scale(.975); transition-duration: 60ms; }

.panel { transition: transform var(--t-med) var(--e-out), box-shadow var(--t-med) var(--e-out); }
.panel:hover { transform: translateY(-4px); /* anulado por .reveal.is-in */ box-shadow: var(--sh-panel), var(--sh-lift); }
.panel__strip { transition: transform 520ms var(--e-out); }
.panel--booth:hover .panel__strip { transform: rotate(-3.2deg) translateY(6px); }
.panel--collage:hover .panel__collage { transform: scale(1.045) rotate(1.2deg); }
.film__card:hover .film__cardIcon { transform: translateY(-3px) scale(1.08); }  /* 420ms, --e-pop */

.badge-btn { transition: transform var(--t-med) var(--e-pop), filter var(--t-med) var(--e-out);
  filter: drop-shadow(0 0 0 rgba(0,0,0,0)); }
.badge-btn:hover { transform: translateY(-3px) scale(1.025); filter: drop-shadow(0 14px 22px rgba(0,0,0,.28)); }

themeToggle.addEventListener('click', () => {
  const next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'
  html.setAttribute('data-theme', next); localStorage.setItem('theme', next)
})
body { transition: background-color var(--t-med) var(--e-soft), color var(--t-med) var(--e-soft); }
